            if isinstance(v, float):
                return round(v,10)
            return v
        nv = [norm(v) for v in vals]
        if not all(v == nv[0] for v in nv):
            coord = wbs[0].cell(row=r, column=c).coordinate
            print(coord, [repr(v) for v in vals])
